<?php require "config.php"; if(!empty($_SESSION["admin_id"])){header("Location: dashboard.php");exit;} $page_title="Admin Login | SFHS";$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$email=trim($_POST["email"]??"");$pw=$_POST["password"]??"";$s=$conn->prepare("SELECT id,full_name,email,password_hash FROM admins WHERE email=? LIMIT 1");$s->bind_param("s",$email);$s->execute();$a=$s->get_result()->fetch_assoc();$s->close();if($a&&password_verify($pw,$a["password_hash"])){session_regenerate_id(true);$_SESSION["admin_id"]=(int)$a["id"];$_SESSION["admin_name"]=$a["full_name"];header("Location: dashboard.php");exit;}else{$error="Incorrect email or password.";}} require "includes/header.php"; ?>
<h1>Administrator login</h1><p class="muted">Authorized school personnel only.</p><form class="form narrow" method="post"><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="btn">Log in</button><p class="muted small">Demo: admin@sfhs.local / Admin@12345</p></form><?php require "includes/footer.php"; ?>